-- Insert 179 food logs (3-4 per student)
INSERT INTO food_logs (student_id, food_item, served_grams, estimated_calories, protein, carbs, fats, logged_at, created_at) SELECT 
id, 'Chicken Biryani', 250, 450, 25, 55, 18, NOW() - INTERVAL '5 days', NOW() FROM students LIMIT 50
UNION ALL SELECT
id, 'Paneer Tikka', 200, 320, 22, 15, 18, NOW() - INTERVAL '4 days', NOW() FROM students LIMIT 40
UNION ALL SELECT
id, 'Dal Rice', 280, 380, 14, 62, 8, NOW() - INTERVAL '3 days', NOW() FROM students LIMIT 39
UNION ALL SELECT
id, 'Roti Sabzi', 180, 240, 10, 45, 5, NOW() - INTERVAL '2 days', NOW() FROM students LIMIT 50;

-- Insert 200 BMI records (4 per student)
WITH bmi_data AS (
  SELECT id, current_bmi FROM students
)
INSERT INTO bmi_records (student_id, bmi, weight, height, status, risk_flag, ai_analysis, created_at)
SELECT id, current_bmi - 0.3, 42, 155, 'normal', 
  CASE WHEN current_bmi > 22 THEN 'at_risk' WHEN current_bmi < 18.5 THEN 'underweight' ELSE 'healthy' END,
  'BMI trend analysis - week 1', NOW() - INTERVAL '21 days' FROM bmi_data
UNION ALL SELECT id, current_bmi - 0.2, 42.5, 155, 'normal', 
  CASE WHEN current_bmi > 22 THEN 'at_risk' WHEN current_bmi < 18.5 THEN 'underweight' ELSE 'healthy' END,
  'BMI trend analysis - week 2', NOW() - INTERVAL '14 days' FROM bmi_data
UNION ALL SELECT id, current_bmi - 0.1, 43, 155, 'normal', 
  CASE WHEN current_bmi > 22 THEN 'at_risk' WHEN current_bmi < 18.5 THEN 'underweight' ELSE 'healthy' END,
  'BMI trend analysis - week 3', NOW() - INTERVAL '7 days' FROM bmi_data
UNION ALL SELECT id, current_bmi, 43.5, 155, 'normal', 
  CASE WHEN current_bmi > 22 THEN 'at_risk' WHEN current_bmi < 18.5 THEN 'underweight' ELSE 'healthy' END,
  'Latest BMI measurement', NOW() FROM bmi_data;

-- Insert 33 health alerts (auto-generated)
INSERT INTO alerts (student_id, alert_type, severity, message, risk_level, resolved, created_at) SELECT
id, 'BMI_ALERT', 'critical', 'Critical: BMI > 24. Nutrition intervention required.', 'critical', false, NOW()
FROM students WHERE current_bmi > 24 LIMIT 8;

INSERT INTO alerts (student_id, alert_type, severity, message, risk_level, resolved, created_at) SELECT
id, 'BMI_ALERT', 'warning', 'At-Risk: BMI 22-24. Dietary modification recommended.', 'at_risk', false, NOW()
FROM students WHERE current_bmi BETWEEN 22 AND 24 LIMIT 5;

INSERT INTO alerts (student_id, alert_type, severity, message, risk_level, resolved, created_at) SELECT
id, 'NUTRITION_ALERT', 'info', 'Underweight: BMI < 18.5. Nutrition enrichment needed.', 'underweight', false, NOW()
FROM students WHERE current_bmi < 18.5 LIMIT 12;

INSERT INTO alerts (student_id, alert_type, severity, message, risk_level, resolved, created_at) SELECT
id, 'HEALTH_ALERT', 'info', 'Healthy: BMI within normal range. Continue current nutrition plan.', 'healthy', false, NOW()
FROM students WHERE current_bmi BETWEEN 18.5 AND 22 LIMIT 8;

-- Verify inserts
SELECT 'Students' as entity, COUNT(*) as count FROM students
UNION ALL SELECT 'Food Logs', COUNT(*) FROM food_logs
UNION ALL SELECT 'BMI Records', COUNT(*) FROM bmi_records
UNION ALL SELECT 'Alerts', COUNT(*) FROM alerts;

